});

export const ZINS_REGELN = {
  AT: { b2b: { aufschlag: 9.2, basis: true, norm: "§ 456 UGB" }, b2c: { fix: 4, norm: "§ 1000 Abs. 1 ABGB" } },
  DE: { b2b: { aufschlag: 9, basis: true, norm: "§ 288 Abs. 2 BGB" }, b2c: { aufschlag: 5, basis: true, norm: "§ 288 Abs. 1 BGB" } },
  CH: { b2b: { fix: 5, norm: "Art. 104 OR" }, b2c: { fix: 5, norm: "Art. 104 OR" } },
};
export const PAUSCHALE_B2B = { betrag: 40, norm: { DE: "§ 288 Abs. 5 BGB", AT: "§ 458 UGB" } };

const zahlOder = (x, std) => (Number.isFinite(Number(x)) && x !== null && x !== "" ? Number(x) : std);

/** Konfiguration prüfen und normalisieren (wirft Error mit deutscher Meldung) */
export function mahnKonfigPruefen(k = {}) {
  const roh = Array.isArray(k.stufen) && k.stufen.length ? k.stufen : MAHN_STANDARD.stufen;
  if (roh.length > 5) throw new Error("Höchstens fünf Mahnstufen.");
  const stufen = roh.map((s, i) => ({
    stufe: i + 1,
    label: String(s.label || `${i + 1}. Stufe`).trim().slice(0, 60),
    abTagen: Math.round(zahlOder(s.abTagen, 0)),
    gebuehr: rund2(zahlOder(s.gebuehr, 0)),
    fristTage: Math.round(zahlOder(s.fristTage, 7)),
  }));
  for (const [i, s] of stufen.entries()) {
    if (s.abTagen < 1 || s.abTagen > 365) throw new Error(`Stufe ${s.stufe}: „ab Tagen“ muss zwischen 1 und 365 liegen.`);
    if (s.gebuehr < 0 || s.gebuehr > 100) throw new Error(`Stufe ${s.stufe}: Mahngebühr zwischen 0 und 100 €.`);
    if (s.fristTage < 3 || s.fristTage > 60) throw new Error(`Stufe ${s.stufe}: Zahlungsfrist zwischen 3 und 60 Tagen.`);
    if (i > 0 && s.abTagen <= stufen[i - 1].abTagen) throw new Error("Die Stufen müssen nach Tagen aufsteigend sein.");
  }
  const basis = k.basiszinssatz === null || k.basiszinssatz === "" || k.basiszinssatz === undefined ? null : Number(k.basiszinssatz);
  if (basis !== null && (!Number.isFinite(basis) || basis < -5 || basis > 15)) throw new Error("Basiszinssatz unplausibel (−5 bis 15 %).");
  const mindest = rund2(zahlOder(k.mindestBetrag, MAHN_STANDARD.mindestBetrag));
  if (mindest < 0 || mindest > 1000) throw new Error("Mindestbetrag zwischen 0 und 1.000 €.");
  return {
    stufen,
    verzugszinsen: !!k.verzugszinsen,
    basiszinssatz: basis,
    pauschaleB2b: !!k.pauschaleB2b,
    mindestBetrag: mindest,
    aufschlagStufe: Math.min(stufen.length, Math.max(1, Math.round(zahlOder(k.aufschlagStufe, stufen.length)))),
  };
}

/** Unternehmer (B2B)? – Annahme: Empfänger mit UID bzw. Organisation */
export const istB2b = (partei = {}) => !!(partei.uid || partei.organisation || partei.firma);

/** Verzugszinssatz in % p. a. (null = nicht berechenbar, z. B. Basiszinssatz fehlt) */
export function verzugszinsSatz(land, b2b, basiszinssatz) {
  const r = (ZINS_REGELN[land] || ZINS_REGELN.AT)[b2b ? "b2b" : "b2c"];
  if (r.fix !== undefined) return { satz: r.fix, norm: r.norm };
  if (basiszinssatz === null || basiszinssatz === undefined || !Number.isFinite(Number(basiszinssatz))) return { satz: null, norm: r.norm };
  return { satz: rund2(Number(basiszinssatz) + r.aufschlag), norm: r.norm };
}

/** Summe der erfassten Zahlungen (Teilzahlungen) eines Belegs */
export const gezahlt = (b) => rund2((b.zahlungen || []).reduce((s, z) => s + (Number(z.betrag) || 0), 0));
/** Offener Betrag einer Rechnung (brutto − Teilzahlungen, nie negativ) */
export const offenerBetrag = (b) => (["bezahlt", "storniert"].includes(b.status) ? 0 : Math.max(0, rund2(Number(b.brutto) - gezahlt(b))));
/** Offene Mahnkosten (Gebühren + Zinsen + Pauschale) */
export const mahnkosten = (b) => rund2((b.mahnungen || []).reduce((s, m) => s + (Number(m.gebuehr) || 0) + (Number(m.zinsen) || 0) + (Number(m.pauschale) || 0), 0));

/**
 * Vorschlag für die nächste Mahnung. Rückgabe null (kein Mahnbeleg möglich) oder
 * { stufe, label, tage, offen, gebuehr, zinsen, zinssatz, zinsNorm, pauschale, gesamt, frist, faellig, grund, eskalation }.
 * faellig=false mit grund → Stufe noch nicht erreicht bzw. Frist der letzten Mahnung läuft.
 */
export function mahnVorschlag(b, heute, konfig = MAHN_STANDARD, { land = "AT" } = {}) {
  const k = konfig?.stufen ? konfig : mahnKonfigPruefen(konfig);
  if (!b || b.beleg !== "rechnung" || b.status !== "offen" || !istDatum(b.faelligAm) || !istDatum(heute)) return null;
  const tage = tageZwischen(b.faelligAm, heute);
  if (tage <= 0) return null;
  const offen = offenerBetrag(b);
  if (offen <= 0) return null;
  const bisher = (b.mahnungen || []).filter((m) => !m.storniert);
  const letzte = bisher.reduce((m, x) => (Number(x.stufe) > Number(m?.stufe || 0) ? x : m), null);
  const letzteStufe = Number(letzte?.stufe || 0);
  const naechste = k.stufen[letzteStufe];
  const basis = { tage, offen, stufe: naechste?.stufe || letzteStufe, label: naechste?.label || "Alle Stufen ausgeschöpft" };
  // Mahnsperre: befristet (Buchhaltung, `bis`) oder unbefristet (z. B. Einspruch des Kunden, `anliegenId` – Team Kundenenergie)
  if (b.mahnsperre && (!b.mahnsperre.bis || heute <= b.mahnsperre.bis)) return { ...basis, faellig: false, grund: `Mahnsperre${b.mahnsperre.bis ? ` bis ${datumDe(b.mahnsperre.bis)}` : ""}: ${b.mahnsperre.grund || "Einwand/Klärung"}`, gesperrt: true };
  if (!naechste) return { ...basis, faellig: false, grund: "Alle Mahnstufen ausgeschöpft – Übergabe an Inkasso/Rechtsanwalt bzw. Klärung prüfen.", eskalation: true };
  if (offen < k.mindestBetrag) return { ...basis, faellig: false, grund: `Offener Betrag unter dem Mindestbetrag (${euro(k.mindestBetrag)}).` };
  if (tage < naechste.abTagen) return { ...basis, faellig: false, grund: `${naechste.label} ab ${naechste.abTagen} Tagen Überfälligkeit (aktuell ${tage}).` };
  const letzteFrist = letzte ? letzte.frist || plusTage(String(letzte.am).slice(0, 10), 7) : null;
  if (letzteFrist && heute <= letzteFrist) return { ...basis, faellig: false, grund: `Frist der ${letzte.label || "letzten Mahnung"} läuft bis ${datumDe(letzteFrist)}.` };
  const b2b = istB2b(b.partei);
  let zinsen = 0;
  let zinssatz = null;
  let zinsNorm = "";
  if (k.verzugszinsen) {
    const z = verzugszinsSatz(land, b2b, k.basiszinssatz);
    zinsNorm = z.norm;
    if (z.satz !== null) {
      zinssatz = z.satz;
      const bereits = rund2(bisher.reduce((s, m) => s + (Number(m.zinsen) || 0), 0));
      zinsen = Math.max(0, rund2((offen * (z.satz / 100) * tage) / 365 - bereits));
    }
  }
  const pauschaleSchon = bisher.some((m) => Number(m.pauschale) > 0);
  const pauschale = k.pauschaleB2b && b2b && ["DE", "AT"].includes(land) && !pauschaleSchon && naechste.stufe >= 2 ? PAUSCHALE_B2B.betrag : 0;
  const gebuehr = naechste.gebuehr;
  const kosten = rund2(mahnkosten({ mahnungen: bisher }) + gebuehr + zinsen + pauschale);
  return {
    ...basis,
    faellig: true,
    gebuehr,
    zinsen,
    zinssatz,
    zinsNorm,
    pauschale,
    pauschaleNorm: pauschale ? PAUSCHALE_B2B.norm[land] : "",
    kostenGesamt: kosten,
    gesamt: rund2(offen + kosten),
    frist: plusTage(heute, naechste.fristTage),
    eskalation: naechste.stufe >= k.aufschlagStufe,
    b2b,
  };
}

/** Mahntext (Brief/PDF/E-Mail) – sachlich, ohne Drohung; Hinweis bei Eskalationsstufe */
export function mahnText(b, m) {
  const zeilen = [
    m.stufe === 1
      ? `sicher ist es Ihrer Aufmerksamkeit entgangen: Zur Rechnung ${b.nummer} vom ${datumDe(b.rechnungsdatum)} (fällig am ${datumDe(b.faelligAm)}) konnten wir noch keinen Zahlungseingang feststellen.`
      : `trotz unserer bisherigen Erinnerung ist die Rechnung ${b.nummer} vom ${datumDe(b.rechnungsdatum)} (fällig am ${datumDe(b.faelligAm)}) weiterhin offen.`,
    `Wir bitten Sie, den offenen Betrag von ${euro(m.gesamt)} bis zum ${datumDe(m.frist)} zu überweisen.`,
    "Sollten Sie die Zahlung bereits veranlasst haben, betrachten Sie dieses Schreiben bitte als gegenstandslos. Bei Rückfragen oder Einwänden zur Rechnung antworten Sie bitte über das Portal.",
  ];
  if (m.eskalation) zeilen.push("Sollte bis zum genannten Termin keine Zahlung eingehen, behalten wir uns weitere Schritte zur Durchsetzung der Forderung vor.");
  return zeilen;
}
// src/lib/plattform/buchhaltung/op.js
//
// Offene-Posten-Liste, Storno-/Korrekturbeleg und Nummernkreise – reine Funktionen.
// Python-Gegenstück: plattform/buchhaltung_kern.py

import { rund2, tageZwischen, istDatum } from "../finanzen/basis.js";
import { gezahlt, mahnkosten, offenerBetrag } from "./mahnwesen.js";

export const ALTERSKLASSEN = [
  { id: "nicht_faellig", label: "nicht fällig", bis: 0 },
  { id: "t1_30", label: "1–30 Tage", bis: 30 },
  { id: "t31_60", label: "31–60 Tage", bis: 60 },
  { id: "t61_90", label: "61–90 Tage", bis: 90 },
  { id: "t90", label: "über 90 Tage", bis: Infinity },
];

export function altersklasse(tage) {
  if (!(tage > 0)) return ALTERSKLASSEN[0];
  return ALTERSKLASSEN.find((k) => tage <= k.bis) || ALTERSKLASSEN[ALTERSKLASSEN.length - 1];
}

/**
 * OP-Liste aus Belegen (Forderungen = Rechnungen offen; Verbindlichkeiten = Gutschriften offen/angewiesen).
 * Rückgabe { posten[], summen: { forderungen, verbindlichkeiten, ueberfaellig, jeKlasse{} } }
 */
export function opListe(belege, heute, { art = "", richtung = "" } = {}) {
  const posten = [];
  for (const b of belege) {
    const forderung = b.beleg === "rechnung";
    if (forderung ? b.status !== "offen" : !["offen", "angewiesen"].includes(b.status)) continue;
    if (art && b.art !== art) continue;
    if (richtung && (richtung === "forderung") !== forderung) continue;
    const offen = forderung ? offenerBetrag(b) : rund2(b.brutto);
    if (offen <= 0) continue;
    const tage = istDatum(b.faelligAm) ? tageZwischen(b.faelligAm, heute) : 0;
    const kl = altersklasse(tage);
    const stufe = Math.max(0, ...(b.mahnungen || []).filter((m) => !m.storniert).map((m) => Number(m.stufe) || 0));
    posten.push({
      id: b.id, nummer: b.nummer, art: b.art, beleg: b.beleg, richtung: forderung ? "forderung" : "verbindlichkeit",
      empfaenger: b.partei?.name || b.empfaenger || "", gesellschaftId: b.gesellschaftId || null, gesellschaft: b.aussteller?.name || b.gesellschaft || "",
      rechnungsdatum: b.rechnungsdatum, faelligAm: b.faelligAm, tageUeberfaellig: Math.max(0, tage), altersklasse: kl.id, altersklasseLabel: kl.label,
      brutto: rund2(b.brutto), gezahlt: gezahlt(b), offen, mahnstufe: stufe, mahnkosten: mahnkosten(b), status: b.status,
    });
  }
  posten.sort((a, b) => b.tageUeberfaellig - a.tageUeberfaellig || String(a.faelligAm).localeCompare(String(b.faelligAm)));
  const jeKlasse = Object.fromEntries(ALTERSKLASSEN.map((k) => [k.id, 0]));
  for (const p of posten.filter((x) => x.richtung === "forderung")) jeKlasse[p.altersklasse] = rund2(jeKlasse[p.altersklasse] + p.offen);
  return {
    posten,
    summen: {
      forderungen: rund2(posten.filter((p) => p.richtung === "forderung").reduce((s, p) => s + p.offen, 0)),
      verbindlichkeiten: rund2(posten.filter((p) => p.richtung === "verbindlichkeit").reduce((s, p) => s + p.offen, 0)),
      ueberfaellig: rund2(posten.filter((p) => p.richtung === "forderung" && p.tageUeberfaellig > 0).reduce((s, p) => s + p.offen, 0)),
      mahnkosten: rund2(posten.reduce((s, p) => s + p.mahnkosten, 0)),
      jeKlasse,
    },
  };
}

// ------------------------------------------------------------------ Storno

export const STORNO_KREIS = "ST";
export const MAHN_KREIS = "MA";

/**
 * Stornobeleg (Rechnungskorrektur/Stornorechnung bzw. Storno-Gutschrift) zu einem Ursprungsbeleg: eigene
 * fortlaufende Nummer, Verweis auf Nummer und Datum des Ursprungs (§ 14 Abs. 4 UStG / § 11 UStG 1994 sinngemäß),
 * Positionen und Steuer mit umgekehrtem Vorzeichen.
 */
export function stornoBeleg(b, { nummer, datum, grund }) {
  const neg = (x) => rund2(-Number(x || 0));
  const gutschrift = b.beleg === "gutschrift";
  return {
    nummer,
    ursprungId: b.id,
    ursprungNummer: b.nummer,
    ursprungDatum: b.rechnungsdatum,
    ursprung: b.beleg,
    art: b.art,
    titel: gutschrift ? "Storno-Gutschrift" : "Stornorechnung (Rechnungskorrektur)",
    datum,
    grund,
    partei: b.partei,
    aussteller: b.aussteller,
    gesellschaftId: b.gesellschaftId || null,
    zeitraum: b.zeitraum,
    positionen: (b.positionen || []).map((p) => ({ ...p, preis: neg(p.preis), betrag: neg(p.betrag) })),
    netto: neg(b.netto),
    steuer: { ...(b.steuer || {}), betrag: neg(b.steuer?.betrag) },
    brutto: neg(b.brutto),
    bereitsGezahlt: b.status === "bezahlt" ? rund2(b.brutto) : gezahlt(b),
    text: `${gutschrift ? "Storno der Gutschrift" : "Storno der Rechnung"} ${b.nummer} vom ${String(b.rechnungsdatum).split("-").reverse().join(".")}. Grund: ${grund}`,
  };
}

/** Ob ein Beleg storniert werden darf – { ok, grund } */
export function stornoErlaubt(b) {
  if (!b) return { ok: false, grund: "Beleg nicht gefunden." };
  if (b.status === "storniert") return { ok: false, grund: "Der Beleg ist bereits storniert." };
  if (b.status === "angewiesen") return { ok: false, grund: "Die Gutschrift ist zur Zahlung angewiesen – zuerst den Zahlungslauf verwerfen bzw. den Beleg zurücksetzen." };
  return { ok: true, grund: "" };
}

/** Nummernkreise → Übersicht { kreis, label, jahr, letzte, naechste } */
export function nummernkreise(kreise, labels, jahr) {
  const aus = [];
  for (const [kreis, jahre] of Object.entries(kreise || {})) {
    for (const [j, n] of Object.entries(jahre || {})) {
      aus.push({ kreis, label: labels[kreis] || kreis, jahr: Number(j), letzte: n ? `${kreis}-${j}-${String(n).padStart(5, "0")}` : "–", anzahl: Number(n) || 0, naechste: `${kreis}-${j}-${String((Number(n) || 0) + 1).padStart(5, "0")}` });
    }
  }
  for (const kreis of Object.keys(labels)) if (!aus.some((x) => x.kreis === kreis && x.jahr === jahr)) aus.push({ kreis, label: labels[kreis], jahr, letzte: "–", anzahl: 0, naechste: `${kreis}-${jahr}-00001` });
  return aus.sort((a, b) => b.jahr - a.jahr || a.kreis.localeCompare(b.kreis));
}

/** Lücken in einer Nummernfolge (Prüfhinweis: fortlaufende Nummerierung) */
export function nummernLuecken(nummern) {
  const je = {};
  for (const n of nummern) {
    const m = /^([A-Z]{2})-(\d{4})-(\d{5})$/.exec(String(n));
    if (m) (je[`${m[1]}-${m[2]}`] ||= []).push(Number(m[3]));
  }
  const aus = [];
  for (const [k, liste] of Object.entries(je)) {
    const s = new Set(liste);
    const max = Math.max(...liste);
    const fehlt = [];
    for (let i = 1; i <= max && fehlt.length < 20; i++) if (!s.has(i)) fehlt.push(`${k}-${String(i).padStart(5, "0")}`);
    if (fehlt.length) aus.push({ kreis: k, fehlt });
  }
  return aus;
}

// src/lib/plattform/buchhaltung/export.js
//
// Buchungsexport an die Steuerberatung – reine Funktionen:
//   DATEV   Buchungsstapel im DATEV-Format (EXTF, Formatkategorie 21), Semikolon, Dezimalkomma, Belegdatum TTMM
//   BMD     Buchungsimport BMD NTCS (CSV, Semikolon): satzart;konto;gkonto;belegnr;belegdat;buchsymbol;buchcode;prozent;steuercode;betrag;steuer;text
//   OP      Offene-Posten-Liste (Excel-CSV)
//
// WICHTIG: Kontenrahmen, Personenkonten, BU-/Steuerschlüssel und Buchungssymbole sind KONFIGURIERBAR und nur als
// Beispiel vorbelegt (DE: SKR03-übliche Nummern, AT: EKR-übliche Nummern). Vor dem ersten Echtimport mit der
// Steuerberatung abstimmen und einen Testimport durchführen (Feldumfang je DATEV-/BMD-Version prüfen).
// Mit ERPNext kommen die Buchungen aus dem Hauptbuch; dieser Export dient dem Eigenbetrieb ohne ERPNext.

import { rund2 } from "../finanzen/basis.js";

export const EXPORT_FORMATE = { datev: "DATEV-Buchungsstapel (CSV)", bmd: "BMD NTCS Buchungsimport (CSV)", op: "Offene-Posten-Liste (CSV)" };

export const KONTEN_STANDARD = Object.freeze({
  datev: {
    beraternummer: "", mandantennummer: "", sachkontenlaenge: 4, wjBeginn: "01-01",
    debitor: "10000", kreditor: "70000", bank: "1200",
    erloes: { provision: "8400", contracting: "8400", provision_rc: "8338", contracting_rc: "8337" },
    aufwand: { pacht: "4210" },
    buSchluessel: {}, // Steuervorlage → BU-Schlüssel (z. B. „DE-USt-19“: "3") – mit Steuerberatung festlegen
  },
  bmd: {
    debitor: "200000", kreditor: "330000", bank: "2800",
    erloes: { provision: "4000", contracting: "4000", provision_rc: "4030", contracting_rc: "4030" },
    aufwand: { pacht: "7400" },
    buchsymbol: { rechnung: "AR", gutschrift: "ER", storno: "AR", zahlung: "BK" },
    steuercode: {}, // Steuervorlage → BMD-Steuercode (z. B. „AT-USt-20“: "1") – mit Steuerberatung festlegen
  },
});

/** Kontenzuordnung zusammenführen (nur bekannte Schlüssel, Werte als Ziffernfolgen) */
export function kontenPruefen(k = {}) {
  const z = (x, std) => (/^[0-9]{1,9}$/.test(String(x ?? "").trim()) ? String(x).trim() : std);
  const t = (x, std) => (/^[0-9A-Za-z]{0,6}$/.test(String(x ?? "").trim()) ? String(x ?? "").trim() : std);
  const map = (o = {}, std = {}) => Object.fromEntries(Object.keys(std).map((key) => [key, z(o?.[key], std[key])]));
  const frei = (o = {}) => Object.fromEntries(Object.entries(o || {}).filter(([a, b]) => /^[A-Za-z0-9-]{2,40}$/.test(a) && /^[0-9A-Za-z]{1,6}$/.test(String(b))).slice(0, 40).map(([a, b]) => [a, String(b)]));
  const D = KONTEN_STANDARD.datev;
  const B = KONTEN_STANDARD.bmd;
  const d = k.datev || {};
  const b = k.bmd || {};
  return {
    datev: {
      beraternummer: /^\d{4,7}$/.test(String(d.beraternummer || "")) ? String(d.beraternummer) : "",
      mandantennummer: /^\d{1,5}$/.test(String(d.mandantennummer || "")) ? String(d.mandantennummer) : "",
      sachkontenlaenge: [4, 5, 6, 7, 8].includes(Number(d.sachkontenlaenge)) ? Number(d.sachkontenlaenge) : D.sachkontenlaenge,
      wjBeginn: /^(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/.test(String(d.wjBeginn || "")) ? d.wjBeginn : D.wjBeginn,
      debitor: z(d.debitor, D.debitor), kreditor: z(d.kreditor, D.kreditor), bank: z(d.bank, D.bank),
      erloes: map(d.erloes, D.erloes), aufwand: map(d.aufwand, D.aufwand), buSchluessel: frei(d.buSchluessel),
    },
    bmd: {
      debitor: z(b.debitor, B.debitor), kreditor: z(b.kreditor, B.kreditor), bank: z(b.bank, B.bank),
      erloes: map(b.erloes, B.erloes), aufwand: map(b.aufwand, B.aufwand),
      buchsymbol: Object.fromEntries(Object.keys(B.buchsymbol).map((key) => [key, t(b.buchsymbol?.[key], B.buchsymbol[key]) || B.buchsymbol[key]])),
      steuercode: frei(b.steuercode),
    },
  };
}

const zahlKomma = (x) => rund2(Math.abs(Number(x) || 0)).toFixed(2).replace(".", ",");
const feld = (s) => `"${String(s ?? "").replace(/"/g, '""').replace(/[\r\n;]+/g, " ").slice(0, 60)}"`;
const ttmm = (iso) => `${String(iso).slice(8, 10)}${String(iso).slice(5, 7)}`;
const ohneBindestrich = (iso) => String(iso || "").replace(/-/g, "");

/**
 * Buchungszeilen (neutral) aus Belegen, Stornos und Zahlungen eines Zeitraums.
 * posten: [{ typ: rechnung|gutschrift|storno|zahlung, datum, nummer, art, brutto, netto, steuerBetrag, steuerVorlage, steuerArt, steuerSatz, text, richtung? }]
 * Rückgabe: [{ datum, beleg, text, betrag, soll: {art, konto}, haben: {art, konto}, steuerVorlage, steuerBetrag, steuerSatz, typ }]
 */
export function buchungen(posten, konten, format = "datev") {
  const k = konten[format];
  const rc = (p) => p.steuerArt === "reverse_charge" || p.steuerArt === "nicht_steuerbar";
  const erloes = (p) => k.erloes[`${p.art}${rc(p) ? "_rc" : ""}`] || k.erloes[p.art] || k.erloes.provision;
  const aus = [];
  for (const p of posten) {
    const basis = { datum: p.datum, beleg: p.nummer, text: String(p.text || "").slice(0, 60), steuerVorlage: p.steuerVorlage || "", steuerBetrag: rund2(p.steuerBetrag || 0), steuerSatz: Number(p.steuerSatz || 0), typ: p.typ };
    if (p.typ === "rechnung") aus.push({ ...basis, betrag: rund2(p.brutto), soll: k.debitor, haben: erloes(p) });
    else if (p.typ === "gutschrift") aus.push({ ...basis, betrag: rund2(p.brutto), soll: k.aufwand.pacht, haben: k.kreditor });
    else if (p.typ === "storno") {
      // Storno kehrt die Ursprungsbuchung um (Rechnung: Erlös an Debitor; Gutschrift: Kreditor an Aufwand)
      if (p.ursprung === "gutschrift") aus.push({ ...basis, betrag: rund2(Math.abs(p.brutto)), soll: k.kreditor, haben: k.aufwand.pacht });
      else aus.push({ ...basis, betrag: rund2(Math.abs(p.brutto)), soll: erloes(p), haben: k.debitor });
    } else if (p.typ === "zahlung") {
      if (p.richtung === "ausgang") aus.push({ ...basis, steuerVorlage: "", steuerBetrag: 0, betrag: rund2(p.brutto), soll: k.kreditor, haben: k.bank });
      else aus.push({ ...basis, steuerVorlage: "", steuerBetrag: 0, betrag: rund2(p.brutto), soll: k.bank, haben: k.debitor });
    }
  }
  return aus.filter((b) => b.betrag > 0).sort((a, b) => String(a.datum).localeCompare(String(b.datum)) || String(a.beleg).localeCompare(String(b.beleg)));
}

/** DATEV-Buchungsstapel (Text; Zeichensatz beim Download Windows-1252/ISO-8859-1) */
export function datevCsv(zeilen, konten, { von, bis, erzeugtAm = new Date().toISOString(), bezeichnung = "OekoInvest Plattform" } = {}) {
  const d = konten.datev;
