// scripts/plattform-test-eg-abrechnung.mjs
//
// Energiegemeinschaften WP4 „Abrechnung, Steuer, Zahlung, Vereinsbuchhaltung“.
//   node scripts/plattform-test-eg-abrechnung.mjs [basis-url]       (--nur-logik: nur Teil A, ohne Server)
