  const g2 = beleg("M2", "gutschrift");
  pruefe(g2.positionen[0].ust.regel === "ERZ_LW" && g2.summen.hinweise.some((h) => /§ 22/.test(h)) && g2.gutschriftZustimmung, "Landwirt: 13 % mit Hinweis § 22, Gutschriftverfahren vereinbart");
