  const u1 = d.erwartet ? unterschied(JSON.parse(JSON.stringify(r)), d.erwartet) : "kein Schnappschuss";
  const u2 = ab.erwartet ? unterschied(JSON.parse(JSON.stringify(x)), ab.erwartet) : "kein Schnappschuss";
