  const x = Math.round(Number(String(betrag ?? "").replace(",", ".")) * 100) / 100;
  if (!(x > 0) || x > belegOffen(b0) + 0.009) throw ungueltig(`Betrag zwischen 0,01 und ${belegOffen(b0).toFixed(2).replace(".", ",")} €.`);
  const t = /^\d\d\d\d-\d\d-\d\d$/.test(datum) && datum <= heute() ? datum : heute();
