    A(d).zahlungen.push({ id: zid, gemeinschaftId: g.id, art: "manuell", status: "gebucht", anzahl: 1, summe: x, belegId: b.id, ...meta(n) });
    b.zahlungen = [...(b.zahlungen || []), { betrag: x, datum: t, art: "manuell", referenz: String(referenz).slice(0, 80), zahlungId: zid }];
    b.status = statusNachZahlung(b);
    for (const z of buchungenAusZahlung(b, { betrag: x, datum: t, id: zid }, { geldkonto: geldkonto === "2700" ? "2700" : "2800" })) A(d).buchungen.push({ id: neueId("EBU"), gemeinschaftId: g.id, ...z, ...meta(n) });
    protokoll(d, n, "eg_abrechnung", "eg_beleg", b.id, `Zahlung ${x.toFixed(2)} € zu ${b.nummer} erfasst`);
    return { beleg: belegAusgabe(b) };
  });
}

export async function abMahnlauf(n, gemeinschaftId, { ausfuehren = false, belegIds = [] } = {}) {
  const db = await bereit();
  const { g } = zugriff(db, n, gemeinschaftId, [["sepa", 1], ["buchhaltung", 1]]);
  const h = heute();
  const ein = einstellungenVon(db, g.id);
  const mVon = new Map(E(db).mitglieder.map((m) => [m.id, m]));
  const vorschlaege = A(db).belege.filter((b) => b.gemeinschaftId === g.id).map((b) => ({ b, v: egMahnvorschlag(b, h, ein.mahnwesen || MAHN_FAIR, { schutzbeduerftig: !!mVon.get(b.mitgliedId)?.schutzbeduerftig }) })).filter((x) => x.v);
  const liste = vorschlaege.map(({ b, v }) => ({ belegId: b.id, nummer: b.nummer, empfaenger: b.empfaenger?.name || "", offen: belegOffen(b), faelligAm: b.faelligAm, ...v }));
  if (!ausfuehren) return { vorschlaege: liste, konfig: ein.mahnwesen || MAHN_FAIR };
  zugriff(db, n, gemeinschaftId, [["sepa", 2]], "Mahnungen erstellen Kassier bzw. Organisator.");
  return aendern((d) => {
    let anzahl = 0;
    for (const x of liste.filter((y) => y.faellig && (!belegIds.length || belegIds.includes(y.belegId)))) {
      const b = A(d).belege.find((y) => y.id === x.belegId);
      const nr = `MA-${h.slice(0, 4)}-${String((A(d).zaehler[g.id]?.[`MA-${h.slice(0, 4)}`] || 0) + 1).padStart(5, "0")}`;
      A(d).zaehler[g.id] = { ...(A(d).zaehler[g.id] || {}), [`MA-${h.slice(0, 4)}`]: (A(d).zaehler[g.id]?.[`MA-${h.slice(0, 4)}`] || 0) + 1 };
      const m = { nr, stufe: x.stufe, label: x.label, am: jetzt(), frist: x.frist, gebuehr: x.gebuehr, zinsen: x.zinsen || 0, pauschale: 0, gesamt: x.gesamt, sozial: x.sozial };
      m.text = mahnText({ nummer: b.nummer, rechnungsdatum: b.datum, faelligAm: b.faelligAm }, m);
      b.mahnungen = [...(b.mahnungen || []), m];
      b.status = "gemahnt";
      const mg = mVon.get(b.mitgliedId);
      const u = mg?.kontoId ? nutzerById(d, mg.kontoId) : null;
      if (u) benachrichtigen(d, u, { art: "system", titel: `${x.label} zu ${b.nummer}`, text: `${g.name}: Bitte begleichen Sie ${x.gesamt.toFixed(2).replace(".", ",")} € bis ${x.frist.split("-").reverse().join(".")}. Bei Fragen oder Zahlungsschwierigkeiten melden Sie sich bitte – wir finden eine Lösung.`, link: "/portal/eg", objektArt: "eg_beleg", objektId: b.id }, { mail: false });
      anzahl++;
    }
    protokoll(d, n, "eg_abrechnung", "eg_gemeinschaft", g.id, `Mahnlauf: ${anzahl} Mahnungen`);
    return { anzahl };
  });
}

// ================================================================ Buchhaltung

function kuIntern(db, g) {
  const jahr = heute().slice(0, 4);
  const belege = A(db).belege.filter((b) => b.gemeinschaftId === g.id && b.nummer && b.status !== "storniert");
  const imJahr = (j) => belege.filter((b) => String(b.datum).startsWith(j));
  const rechnungen = (j) => imJahr(j).filter((b) => b.typ === "rechnung" || (b.typ === "storno" && b.ursprungTyp === "rechnung"));
  const gut = imJahr(jahr).filter((b) => b.typ === "gutschrift" || (b.typ === "storno" && b.ursprungTyp === "gutschrift"));
  const monate = Math.max(1, new Set(imJahr(jahr).map((b) => b.von.slice(0, 7))).size);
  return kuMonitor({
    ustStatus: g.ustStatus, jahr: Number(jahr), monateErfasst: monate, umsatzBrutto: rechnungen(jahr).reduce((s, b) => s + b.summen.brutto, 0), vorjahrBrutto: rechnungen(String(Number(jahr) - 1)).reduce((s, b) => s + b.summen.brutto, 0),
    rcSteuer: gut.reduce((s, b) => s + (b.summen.rcSteuer || 0), 0), vorsteuer: gut.reduce((s, b) => s + b.summen.ust, 0), umsatzNetto: rechnungen(jahr).reduce((s, b) => s + b.summen.netto, 0),
  });
}

