  const ea = eaRechnung(buchungen, j, { anfang, offeneForderungen: offen.filter((b) => b.typ === "rechnung").reduce((s, b) => s + belegOffen(b), 0), offeneVerbindlichkeiten: offen.filter((b) => b.typ === "gutschrift").reduce((s, b) => s + belegOffen(b), 0) });
  const quartale = [1, 2, 3, 4].map((q) => uvaVorbereitung(belege, { von: `${j}-${String(q * 3 - 2).padStart(2, "0")}-01`, bis: `${j}-${String(q * 3).padStart(2, "0")}-${q === 1 || q === 4 ? "31" : "30"}`, ustStatus: g.ustStatus }));
  return {
    gemeinschaft: { id: g.id, name: g.name, ustStatus: g.ustStatus, rechtsform: g.rechtsform }, jahr: Number(j),
    buchungen: buchungen.filter((b) => String(b.datum).startsWith(j)).sort((x, y) => (x.datum < y.datum ? 1 : -1)), ea, kassabuch: kassabuch(buchungen.filter((b) => String(b.datum).startsWith(j)), { anfangsbestand: anfang.kassa }),
    uva: quartale, ku: kuIntern(db, g), luecken: belegLuecken(belege), pruefvermerke: a.pruefvermerke.filter((x) => x.gemeinschaftId === g.id), konten: BUCHUNG_KATEGORIEN, exportArten: EXPORT_ARTEN, kontenplan: EG_KONTEN,
    rechte: egRechteVon(k), stufen: stufen(k), heute: heute(),
  };
}

