  return aendern((d) => {
    const neu = { id: neueId("EBU"), gemeinschaftId: g.id, ...b, ...meta(n) };
    const kb = kassabuch([...A(d).buchungen.filter((x) => x.gemeinschaftId === g.id && x.datum.slice(0, 4) === b.datum.slice(0, 4)), neu], { anfangsbestand: A(d).anfang[g.id]?.[b.datum.slice(0, 4)]?.kassa || 0 });
    if (b.geldkonto === "2700" && kb.fehler.length) throw ungueltig(kb.fehler[0]);
    A(d).buchungen.push(neu);
    protokoll(d, n, "eg_abrechnung", "eg_buchung", neu.id, `Buchung ${b.belegNr}: ${b.text} ${b.betrag.toFixed(2)} €`);
    return { buchung: neu };
  });
}

export async function abPruefvermerk(n, gemeinschaftId, { daten = {} } = {}) {
  const db = await bereit();
  const { g } = zugriff(db, n, gemeinschaftId, [["buchhaltung_pruefen", 2]], "Den Prüfvermerk erteilt die Rechnungsprüfung.");
  const v = fach(() => pruefvermerkBereinigen(daten));
  return aendern((d) => {
    const x = { id: neueId("EBU"), gemeinschaftId: g.id, ...v, jahr: v.jahr || Number(heute().slice(0, 4)) - 1, prueferId: n.id, pruefer: nameVon(d, n.id), am: jetzt() };
    x.hash = sha256(JSON.stringify([x.gemeinschaftId, x.jahr, x.ergebnis, x.text, x.stichproben, x.prueferId, x.am]));
    A(d).pruefvermerke.push(x);
    protokoll(d, n, "eg_abrechnung", "eg_gemeinschaft", g.id, `Prüfvermerk ${x.jahr}: ${x.ergebnis}`);
    return { pruefvermerk: x };
  });
}

export async function abExport(n, gemeinschaftId, { art = "ea", jahr = "" } = {}) {
  const db = await bereit();
  const { g } = zugriff(db, n, gemeinschaftId, [["buchhaltung", 1]], "Exporte für Kassier, Vorstand, Rechnungsprüfung und Organisator.");
  const j = /^20\d\d$/.test(String(jahr)) ? Number(jahr) : Number(heute().slice(0, 4));
  if (!EXPORT_ARTEN[art] && art !== "paket") throw ungueltig("Unbekannte Exportart.");
  const a = A(db);
  const buchungen = a.buchungen.filter((b) => b.gemeinschaftId === g.id);
  const belege = a.belege.filter((b) => b.gemeinschaftId === g.id);
  const anfang = a.anfang[g.id]?.[String(j)] || { bank: 0, kassa: 0 };
  const ea = eaRechnung(buchungen, j, { anfang });
  const kassa = kassabuch(buchungen.filter((b) => String(b.datum).startsWith(String(j))), { anfangsbestand: anfang.kassa });
  await aendern((d) => protokoll(d, n, "eg_abrechnung", "eg_gemeinschaft", g.id, `Export ${art} ${j}`));
  if (art === "paket") {
    const inhalt = JSON.stringify({ gemeinschaft: { name: g.name, zvr: g.zvrZahl, ustStatus: g.ustStatus }, jahr: j, erstelltAm: jetzt(), ea, kassabuch: kassa, uva: [1, 2, 3, 4].map((q) => uvaVorbereitung(belege, { von: `${j}-${String(q * 3 - 2).padStart(2, "0")}-01`, bis: `${j}-${String(q * 3).padStart(2, "0")}-31`, ustStatus: g.ustStatus })), belegjournal: belege.filter((b) => String(b.datum).startsWith(String(j))).map((b) => ({ nummer: b.nummer, typ: b.typ, datum: b.datum, mitgliedsnummer: b.mitgliedsnummer, netto: b.summen.netto, ust: b.summen.ust, brutto: b.summen.brutto, status: b.status, hash: b.hash })), luecken: belegLuecken(belege), pruefvermerke: a.pruefvermerke.filter((x) => x.gemeinschaftId === g.id), eigendeckungKwh: a.perioden.filter((p) => p.gemeinschaftId === g.id && p.status !== "storniert" && !p.probe && p.von.startsWith(String(j))).reduce((s, p) => s + (p.kennzahlen?.eigendeckung || 0), 0), hinweis: "Jahresabschluss-Paket für Rechnungsprüfung und Steuerberatung (VerG § 21). Eigendeckung: Grundlage der Erklärung zur Elektrizitätsabgabe (bilanzielle Aufzeichnungen, BMF 03.11.2023)." }, null, 1);
    return { dateiname: `${(g.kurzname || "EG").replace(/\s+/g, "-")}_Jahresabschluss_${j}.json`, inhalt, mime: "application/json" };
  }
  return exportErzeugen(art, { buchungen, belege, jahr: j, gemeinschaft: g, konten: einstellungenVon(db, g.id).konten || {}, ea, kassa });
}

export async function abJahresbescheinigung(n, mitgliedId, { jahr = "" } = {}) {
  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
  const db = await bereit();
  const m = E(db).mitglieder.find((x) => x.id === String(mitgliedId || ""));
  if (!m) throw nichtGefunden("Mitglied nicht gefunden.");
  const g = gemeinschaftVon(db, m.gemeinschaftId);
  const k = kontext(db, n, g);
  if (!(m.kontoId && m.kontoId === n.id) && egStufe(k, "buchhaltung") < 1) throw nichtGefunden("Mitglied nicht gefunden.");
  const j = /^20\d\d$/.test(String(jahr)) ? Number(jahr) : Number(heute().slice(0, 4)) - 1;
  const zps = E(db).teilnahmen.filter((t) => t.mitgliedId === m.id).map((t) => E(db).zaehlpunkte.find((z) => z.id === t.zaehlpunktId)).filter((z) => z?.anlageId);
  const kwp = zps.reduce((s, z) => s + (Number(E(db).anlagen.find((a) => a.id === z.anlageId)?.kwp) || 0), 0);
  const gut = A(db).belege.filter((b) => b.mitgliedId === m.id && (b.typ === "gutschrift" || (b.typ === "storno" && b.ursprungTyp === "gutschrift")));
  return { gemeinschaft: { name: g.name }, mitglied: { mitgliedsnummer: m.mitgliedsnummer, name: m.person?.firma || `${m.person?.vorname || ""} ${m.person?.nachname || ""}`.trim() }, ...jahresbescheinigung(gut, { jahr: j, mitglied: m, anlagenKwp: kwp }) };
}

export async function abEinstellungenSpeichern(n, gemeinschaftId, { daten = {} } = {}) {
  const db = await bereit();
  const { g, k } = zugriff(db, n, gemeinschaftId, [["tarife", 2], ["buchhaltung", 2]], "Einstellungen ändern Vorstand (Tarifgruppen, Rabatte) bzw. Kassier (Zahlungsziel, Mahnwesen).");
  const s = stufen(k);
  return aendern((d) => {
    const alt = einstellungenVon(d, g.id);
    const neu = { ...alt };
    const zahl = (v, min, max) => (v === null || v === "" || v === undefined ? null : Number.isFinite(Number(String(v).replace(",", "."))) ? Math.min(max, Math.max(min, Number(String(v).replace(",", ".")))) : null);
    if (s.buchhaltung >= 2) {
      if (daten.zahlungszielTage !== undefined) neu.zahlungszielTage = Math.round(zahl(daten.zahlungszielTage, 7, 60) ?? 14);
      if (daten.mitgliedsbeitragArt) neu.mitgliedsbeitragArt = daten.mitgliedsbeitragArt === "echt" ? "echt" : "unecht";
      if (daten.aufrechnung !== undefined) neu.aufrechnung = !!daten.aufrechnung;
      if (daten.gutschriftverfahren && typeof daten.gutschriftverfahren === "object") {
        for (const [mid, v] of Object.entries(daten.gutschriftverfahren).slice(0, 2000)) if (E(d).mitglieder.some((m) => m.id === mid && m.gemeinschaftId === g.id)) neu.gutschriftverfahren = { ...neu.gutschriftverfahren, [mid]: { zugestimmtAm: /^\d\d\d\d-\d\d-\d\d$/.test(v?.zugestimmtAm || "") ? v.zugestimmtAm : "", widersprochenAm: /^\d\d\d\d-\d\d-\d\d$/.test(v?.widersprochenAm || "") ? v.widersprochenAm : "" } };
      }
    }
    if (s.tarife >= 2 || s.buchhaltung >= 2) {
      for (const f of ["netzApCt", "efbApCt", "referenzLieferantCt", "referenzEinspeisungCt"]) if (daten[f] !== undefined) neu[f] = zahl(daten[f], 0, 100);
    }
    if (s.tarife >= 2) {
      if (Array.isArray(daten.gruppen)) neu.gruppen = daten.gruppen.slice(0, 20).map((x, i) => ({ id: String(x.id || `G${i + 1}`).slice(0, 20), label: String(x.label || "Tarifgruppe").slice(0, 80), mitgliedIds: (x.mitgliedIds || []).map(String).slice(0, 2000), mitgliedArten: (x.mitgliedArten || []).filter((a) => MITGLIED_ARTEN[a]), bezugspreisCt: zahl(x.bezugspreisCt, 0, 100), einspeisepreisCt: zahl(x.einspeisepreisCt, 0, 100), grund: String(x.grund || "").slice(0, 200) }));
      if (Array.isArray(daten.rabatte)) neu.rabatte = daten.rabatte.slice(0, 20).map((x, i) => ({ id: String(x.id || `R${i + 1}`).slice(0, 20), label: String(x.label || "Rabatt").slice(0, 80), art: x.art === "betrag" ? "betrag" : "pct", wert: zahl(x.wert, 0, x.art === "betrag" ? 1000 : 100) || 0, bezug: ["energie", "gebuehren", "alles"].includes(x.bezug) ? x.bezug : "energie", mitgliedIds: (x.mitgliedIds || []).map(String).slice(0, 2000), mitgliedArten: (x.mitgliedArten || []).filter((a) => MITGLIED_ARTEN[a]), gueltigAb: String(x.gueltigAb || ""), gueltigBis: String(x.gueltigBis || ""), beschluss: String(x.beschluss || "").slice(0, 120) }));
    }
    A(d).einstellungen[g.id] = neu;
    protokoll(d, n, "eg_abrechnung", "eg_gemeinschaft", g.id, "Abrechnungseinstellungen geändert");
    return { einstellungen: neu };
  });
}

/** Mandat prüfen (für die Mitgliederliste im Kassa-Bereich) */
export async function abMandate(n, gemeinschaftId) {
  const db = await bereit();
  const { g } = zugriff(db, n, gemeinschaftId, [["sepa", 1]]);
  const h = heute();
  return { mandate: E(db).mitglieder.filter((m) => m.gemeinschaftId === g.id && ["aufgenommen", "aktiv", "gekuendigt"].includes(m.status)).map((m) => ({ mitgliedId: m.id, mitgliedsnummer: m.mitgliedsnummer, name: m.person?.firma || `${m.person?.vorname || ""} ${m.person?.nachname || ""}`.trim(), referenz: m.sepaMandat?.referenz || "", datum: m.sepaMandat?.datum || "", iban: MASKE(m.iban), pruefung: mandatPruefen(m.sepaMandat || {}, { iban: m.iban, heute: h }) })) };
}

