  const x = Math.round(Number(String(betrag ?? "").replace(",", ".")) * 100) / 100;
  const offen = belegOffen(b0);
  if (!(x > 0) || x > offen + 0.009) throw ungueltig(`Betrag zwischen 0,01 € und ${eur(offen)}.`);
  const t = datumOk(datum) && datum <= heute() ? datum : heute();
  return aendern((d) => {
