// /portal/eg/[id]/verwaltung – Einstieg der Organe (Obmann/Vorstand, Kassier, Schriftführung, Rechnungsprüfung) in ihre
// Gemeinschaft: offene Aufgaben (Aufnahmen, Zustimmungen beim Netzbetreiber), Kennzahlen, Mitgliederliste (Details je Recht),
// Organe, Tarife mit Vorschlag/Beschluss. Rechte je Kontext-Rolle (eg/rechte.js); ohne Rolle 404. WP1.

import { CalendarClock, ClipboardCheck, Factory, ReceiptText, Users } from "lucide-react";
import { Badge, Hinweis, Karte, Kennzahl, Leer, SeitenKopf, Tabelle, zelle } from "@/components/Portal/ui";
import { Klappe } from "@/components/Portal/Mitglied/teile";
import EgReiter from "@/components/Portal/EG/Stamm/EgReiter";
import { OrganNeu, TarifNeu } from "@/components/Portal/EG/Stamm/Formulare";
import { MitgliederTabelle } from "@/components/Portal/EG/Stamm/Mitglieder";
import { AufnahmeKnoepfe } from "@/components/Portal/EG/Stamm/Aufnahme";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";
import { GEMEINSCHAFT_STATUS, TARIF_STATUS, TEILNAHME_STATUS } from "@/lib/plattform/eg/modell";
import { datum } from "@/lib/plattform/format";

export const metadata = { title: "Verwaltung der Energiegemeinschaft" };
const zahl = (x, s = 0) => (x === null || x === undefined ? "–" : Number(x).toLocaleString("de-DE", { maximumFractionDigits: s }));

export default async function Verwaltung({ params }) {
  const n = await portalNutzer();
  const { id } = await params;
  const d = await laden(() => egBackend().egVerwaltung(n, id));
  const g = d.gemeinschaft;
  const r = d.rechte;
  const url = `/api/portal/eg/${g.id}/verwaltung`;
  const z = g.kennzahlen;
  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow={`Verwaltung · ${d.rollenLabels.join(", ")}`} titel={g.name} text={`${g.modellLabel} · ${g.zonelevelLabel} · ${g.netzbetreiberNamen.join(", ")}`}>
        <div className="mt-3"><Badge ton={GEMEINSCHAFT_STATUS[g.status]?.ton}>{g.statusLabel}</Badge></div>
      </SeitenKopf>
      <EgReiter gemeinschaftId={g.id} aktiv="verwaltung" art="organ" rechte={r} />
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kennzahl label="Aktive Mitglieder" wert={zahl(z.mitgliederAktiv)} hinweis={z.mitgliederOffen ? `${z.mitgliederOffen} Anträge offen` : undefined} icon={Users} />
        <Kennzahl label="Aktive Zählpunkte" wert={zahl(z.zaehlpunkteAktiv)} hinweis={`${z.teilnahmenOffen} in Anmeldung`} icon={ClipboardCheck} />
        <Kennzahl label="Erzeugungsleistung" wert={`${zahl(z.erzeugungsleistungKw, 1)} kW`} hinweis={z.lieferantenpflichten ? "§ 69 ElWG: Lieferantenpflichten" : undefined} icon={Factory} />
        <Kennzahl label="Tarif" wert={g.tarifAktuell ? `${zahl(g.tarifAktuell.bezugspreisCt, 2)} ct` : "–"} hinweis={g.tarifAktuell ? `Einspeisung ${zahl(g.tarifAktuell.einspeisepreisCt, 2)} ct/kWh` : "kein gültiger Tarif"} icon={ReceiptText} />
      </div>

      <Karte titel="Zu erledigen" aktion={<CalendarClock aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
        {d.aufgaben.length ? (
          <ul className="divide-y divide-ink-100">
            {d.aufgaben.map((a, i) => (
              <li key={i} className="flex flex-wrap items-center justify-between gap-3 py-3 text-[14.5px] text-ink-800">
                <span>{a.text}</span>
                {a.art === "aufnahme" && r.mitglied_aufnehmen >= 2 && <AufnahmeKnoepfe mitgliedId={a.mitgliedId} url={url} />}
              </li>
            ))}
          </ul>
        ) : <Leer titel="Alles erledigt" text="Keine offenen Aufnahmen oder Zustimmungen." />}
      </Karte>

      {d.hinweise.length > 0 && <Hinweis ton={d.hinweise.some((h) => h.stufe === "fehler") ? "warn" : "info"} titel="Hinweise"><ul className="list-disc space-y-1 pl-5">{d.hinweise.map((h, i) => <li key={i}>{h.text}</li>)}</ul></Hinweis>}

      <Karte titel="Teilnahmen nach Status">
        <div className="flex flex-wrap gap-2">{Object.entries(d.teilnahmenStatus).map(([s, k]) => <Badge key={s} ton={TEILNAHME_STATUS[s]?.ton}>{TEILNAHME_STATUS[s]?.label}: {k}</Badge>)}</div>
      </Karte>

      <Karte titel="Mitglieder" untertitel={r.stammdaten >= 1 ? "mit Zählpunkten und Teilnahmen" : "Name und Status"} aktion={<Users aria-hidden="true" className="h-5 w-5 text-ov-600" />}>
// /portal/admin/eg/[id] – Backoffice: eine Energiegemeinschaft. Reiter (?reiter=): stammdaten (Stammdaten, Status, Organe,
// Hinweise), mitglieder (Mitglieder & Zählpunkte mit Massenbearbeitung, CSV-Import/-Export), anlagen (Anlagen, Tarife,
// Verteilschlüssel). Weitere Reiter anderer Pakete über EgReiter (EDA, Energiedaten, Abrechnung …). WP1.

import { Factory, Landmark, ReceiptText, ScrollText, ShieldCheck, Users } from "lucide-react";
import { Angaben, Badge, Hinweis, Karte, Kennzahl, SeitenKopf, Tabelle, zelle } from "@/components/Portal/ui";
import { Klappe } from "@/components/Portal/Mitglied/teile";
import EgReiter from "@/components/Portal/EG/Stamm/EgReiter";
import { AnlageNeu, OrganBeenden, OrganNeu, StammdatenFormular, StatusWechsel, TarifNeu } from "@/components/Portal/EG/Stamm/Formulare";
import { CsvImport, MitgliedNeu, MitgliederTabelle, TeilnahmeKorrektur } from "@/components/Portal/EG/Stamm/Mitglieder";
import { portalNutzer, laden } from "@/lib/plattform/server/seite";
import { egBackend } from "@/lib/plattform/backend/eg";
import { ANLAGE_ARTEN, GEMEINSCHAFT_STATUS, NUTZUNGSMODELLE, TARIF_STATUS } from "@/lib/plattform/eg/modell";
import { datum } from "@/lib/plattform/format";

export const metadata = { title: "Energiegemeinschaft" };
const zahl = (x, s = 0) => (x === null || x === undefined || x === "" ? "–" : Number(x).toLocaleString("de-DE", { maximumFractionDigits: s }));
const CSV_SPALTEN = ["mitgliedsnummer", "art", "vorname", "nachname", "firma", "strasse", "plz", "ort", "email", "iban", "sepa_referenz", "sepa_datum", "steuerstatus", "uid", "zaehlpunkt", "richtung", "teilnahmefaktor", "kwp"];

export default async function EgDetail({ params, searchParams }) {
  const n = await portalNutzer({ admin: true });
  const { id } = await params;
  const sp = (await searchParams) || {};
  const reiter = ["mitglieder", "anlagen"].includes(sp.reiter) ? sp.reiter : "stammdaten";
  const d = await laden(() => egBackend().egGemeinschaft(n, id));
  const g = d.gemeinschaft;
  const r = d.rechte;
  const url = `/api/admin/eg/${g.id}`;
  const z = g.kennzahlen;
  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow={`${g.modellKurz} · Zonelevel ${g.zonelevel} · ${g.netzbetreiberNamen.join(", ") || "ohne Netzbetreiber"}`} titel={g.name} text={g.gemeinschaftsId ? `Gemeinschafts-ID ${g.gemeinschaftsId}${g.marktpartnerId ? ` · Marktpartner ${g.marktpartnerId}` : ""}` : "Gemeinschafts-ID noch nicht vergeben"}>
        <div className="mt-3 flex flex-wrap gap-2"><Badge ton={GEMEINSCHAFT_STATUS[g.status]?.ton}>{g.statusLabel}</Badge>{d.rollen.length > 0 && <Badge ton="info">{d.rollen.join(", ")}</Badge>}{g.demo && <Badge>Demo</Badge>}</div>
      </SeitenKopf>
      <EgReiter gemeinschaftId={g.id} aktiv={reiter} art="admin" />
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kennzahl label="Aktive Mitglieder" wert={zahl(z.mitgliederAktiv)} hinweis={z.mitgliederOffen ? `${z.mitgliederOffen} Anträge offen` : undefined} icon={Users} />
        <Kennzahl label="Aktive Zählpunkte" wert={zahl(z.zaehlpunkteAktiv)} hinweis={`${z.verbrauchAktiv} Verbrauch · ${z.erzeugungAktiv} Erzeugung`} icon={Landmark} />
        <Kennzahl label="Erzeugungsleistung" wert={`${zahl(z.erzeugungsleistungKw, 1)} kW`} hinweis={z.lieferantenpflichten ? "§ 69 ElWG: Lieferantenpflichten" : "unter der § 69-Schwelle"} icon={Factory} />
        <Kennzahl label="Netzentgelt (heute)" wert={g.netzentgelt?.reduktionPct ? `−${g.netzentgelt.reduktionPct} %` : "–"} hinweis={g.netzentgelt?.status === "platzhalter" ? "Platzhalter neue SNE-VO" : g.netzentgelt?.quelle} icon={ShieldCheck} />
// src/lib/plattform/server/seite.js
//
// Sitzung in Server-Komponenten (Seiten, Layouts). Die Middleware prüft vorab nur die
// Signatur; hier wird der Nutzer frisch geladen (Rollen, Sperre, Sitzungsversion).

import { cookies, headers } from "next/headers";
import { redirect, notFound } from "next/navigation";
import { backend } from "../backend";
import { cookieName, tokenPruefen } from "../sitzung";
import { PlattformFehler } from "../fehler";
import { seitenRechtOk } from "./rechte"; // Backoffice-Unterrollen

export async function aktuellerNutzer() {
  const token = (await cookies()).get(cookieName())?.value;
  if (!token) return null;
  const s = await tokenPruefen(token);
  if (!s) return null;
  const u = await backend().nutzerFuerSitzung(s.nutzerId, { sitzungId: s.sitzungId }); // Sitzungseintrag muss bestehen
  if (!u || !u.aktiv || (u.sitzungVersion || 0) !== s.version) return null;
  return u;
}

/** Aktuellen Pfad (von der Middleware als Kopfzeile gesetzt) für ?weiter= */
async function aktuellerPfad() {
  const h = await headers();
  const p = h.get("x-oi-pfad") || "/portal";
  return p.startsWith("/portal") ? p : "/portal";
}

/**
 * Für Portalseiten: Nutzer oder Weiterleitung zum Login.
 * rollen: mindestens eine davon (admin darf immer), sonst 404 (keine Existenz verraten).
 */
export async function portalNutzer({ rollen, admin } = {}) {
  const u = await aktuellerNutzer();
  if (!u) redirect(`/login?weiter=${encodeURIComponent(await aktuellerPfad())}`);
  // Pflicht-2FA noch nicht eingerichtet → nur die Sicherheitsseite
  if (u.zweiFaktorPflichtOffen && !(await aktuellerPfad()).startsWith("/portal/sicherheit")) redirect("/portal/sicherheit?pflicht=1");
  const istAdmin = u.rollen.includes("admin");
  if (admin && !istAdmin) notFound();
  if (admin && istAdmin && !seitenRechtOk(u, await aktuellerPfad())) notFound(); // Bereich ohne Leserecht der Unterrolle
  if (rollen && !istAdmin && !rollen.some((r) => u.rollen.includes(r))) notFound();
  return u;
}

export const istAdmin = (u) => !!u?.rollen?.includes("admin");
export const hatRolle = (u, ...rollen) => istAdmin(u) || rollen.some((r) => u?.rollen?.includes(r));

/** Backend-Aufruf in Seiten: 403/404 → notFound(), sonst weiterwerfen */
export async function laden(fn) {
  try {
    return await fn();
  } catch (e) {
    if (e instanceof PlattformFehler && [403, 404].includes(e.status)) notFound();
    throw e;
  }
}

