];

/**
 * Kassa & Buchhaltung. `p` = abPerioden, `bh` = abBuchungen (oder null ohne Recht), `mahn` = abMahnlauf, `mandate`, `belege`.
 */
export function KasseAnsicht({ p, bh, mahn, mandate, belege = [], tab, basis, kontoId }) {
