import os

APP = r"C:\Users\SALEADMIN\Downloads\Oekoinvest-Web\src\app\portal"

ABR = """// {pfad} – {kopf}
// Perioden (Monat/Quartal/Jahr/Schluss, Probe-Abrechnung für Wechsler), Vorschau mit Prüfungen und Prüfpfad je Belegzeile,
// Vier-Augen-Freigabe (Kassier + Obmann/Vorstand), Versand, Storno/Korrektur. Rechte je Gemeinschaft prüft das Backend (WP4).

import {{ SeitenKopf }} from "@/components/Portal/ui";
import EgReiter from "@/components/Portal/EG/Stamm/EgReiter";
import {{ AbrechnungAnsicht }} from "@/components/Portal/EG/Abrechnung/Ansichten";
import {{ portalNutzer, laden }} from "@/lib/plattform/server/seite";
import {{ egBackend }} from "@/lib/plattform/backend/eg";

export const metadata = {{ title: "{titel}" }};

export default async function Seite({{ params, searchParams }}) {{
  const n = await portalNutzer({admin});
  const {{ id }} = await params;
  const sp = (await searchParams) || {{}};
  const b = egBackend();
  const d = await laden(() => b.abPerioden(n, id));
  const wahl = d.perioden.find((p) => p.id === sp.periode) || d.perioden.find((p) => !["abgeschlossen", "storniert"].includes(p.status)) || d.perioden[0] || null;
  const pd = wahl ? await laden(() => b.abPeriodeAktion(n, wahl.id, {{ aktion: "lesen" }})) : null;
  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow="{eyebrow}" titel={{`Abrechnung · ${{d.gemeinschaft.name}}`}} text="Abgerechnet werden die Viertelstundenwerte des Netzbetreibers (Eigendeckung, eingebrachte Erzeugung). Jede Zahl ist bis zur Quelle nachvollziehbar; freigegeben wird nach dem Vier-Augen-Prinzip." />
      <EgReiter gemeinschaftId={{id}} aktiv="abrechnung" art="{art}"{rechte} />
      <AbrechnungAnsicht d={{d}} pd={{pd}} basis="{basis}" kontoId={{n.id}} />
    </div>
  );
}}
"""

KASSE = """// {pfad} – {kopf}
// Zahlungen (SEPA-Lastschrift/-Überweisung mit Vier-Augen, camt-Abgleich, Mandate, offene Posten), Mahnwesen mit fairen
// Gebühren, Kassabuch und Buchungen, Einnahmen-Ausgaben-Rechnung, UVA-Vorbereitung, Kleinunternehmer-Monitor, Exporte
// (BMD, RZL, DATEV), Jahresabschluss-Paket und Prüfvermerk der Rechnungsprüfung. Rechte prüft das Backend (WP4).

import {{ SeitenKopf }} from "@/components/Portal/ui";
import EgReiter from "@/components/Portal/EG/Stamm/EgReiter";
import {{ KasseAnsicht }} from "@/components/Portal/EG/Abrechnung/Ansichten";
import {{ portalNutzer, laden }} from "@/lib/plattform/server/seite";
import {{ egBackend }} from "@/lib/plattform/backend/eg";

export const metadata = {{ title: "{titel}" }};

const versuch = async (fn) => {{
  try {{
    return await fn();
  }} catch {{
    return null;
  }}
}};

export default async function Seite({{ params, searchParams }}) {{
  const n = await portalNutzer({admin});
  const {{ id }} = await params;
  const sp = (await searchParams) || {{}};
  const b = egBackend();
  const p = await laden(() => b.abPerioden(n, id));
  const [bh, mahn, mandate, belege] = await Promise.all([
    p.stufen.buchhaltung >= 1 ? versuch(() => b.abBuchungen(n, id, {{ jahr: sp.jahr || "" }})) : null,
    versuch(() => b.abMahnlauf(n, id, {{}})),
    p.stufen.sepa >= 1 ? versuch(() => b.abMandate(n, id)) : null,
    versuch(() => b.abBelege(n, {{ gemeinschaftId: id }})),
  ]);
  return (
    <div className="space-y-6">
      <SeitenKopf eyebrow="{eyebrow}" titel={{`{kurz} · ${{p.gemeinschaft.name}}`}} text="Zahlungsverkehr, Vereinsbuchhaltung und Steuer an einem Ort – mit Vier-Augen-Prinzip für Zahlungsdateien und einem Prüfpfad für die Rechnungsprüfung. Keine Steuerberatung." />
      <EgReiter gemeinschaftId={{id}} aktiv="{reiter}" art="{art}"{rechte} />
      <KasseAnsicht p={{p}} bh={{bh}} mahn={{mahn}} mandate={{mandate}} belege={{belege?.belege || []}} tab={{sp.tab}} basis="{basis}" kontoId={{n.id}} />
    </div>
  );
}}
"""

seiten = [
