    pruefe(r.status === 422, "Kassabuch darf nicht negativ werden → 422", r.status);
    r = await kassier.post(`${api}/buchhaltung`, { aktion: "pruefvermerk", daten: { ergebnis: "ohne_beanstandung" } });
