  r = await kassier.get(`${api}/mahnlauf`);
  pruefe(r.status === 200 && Array.isArray(r.json.vorschlaege) && r.json.konfig.stufen[0].gebuehr === 0, `Mahnvorschläge (${r.json.vorschlaege?.length}), erste Stufe gebührenfrei`, r.status);
